/**
 * NavMeshGridHelper - 3D debug visualization for navigation mesh.
 *
 * @extends THREE.Object3D
 */
export class NavMeshGridHelper {
    /**
     * Create a navmesh grid helper.
     *
     * @param {NavMeshGrid} navMeshGrid - The navmesh grid to visualize.
     * @param {Object} [options={}] - Configuration options.
     * @param {boolean} [options.showPolygons=true] - Show polygon surfaces.
     * @param {boolean} [options.showEdges=true] - Show polygon edges.
     * @param {boolean} [options.showPortals=false] - Show portal edges (connections).
     * @param {number} [options.polygonColor=0x00ff88] - Polygon fill color.
     * @param {number} [options.edgeColor=0x0088ff] - Edge line color.
     * @param {number} [options.portalColor=0xff8800] - Portal edge color.
     * @param {number} [options.opacity=0.3] - Polygon opacity.
     * @param {number} [options.yOffset=0.05] - Y offset above surfaces.
     * @param {number} [options.updateInterval=1000] - Update interval in ms.
     */
    constructor(navMeshGrid: NavMeshGrid, options?: {
        showPolygons?: boolean;
        showEdges?: boolean;
        showPortals?: boolean;
        polygonColor?: number;
        edgeColor?: number;
        portalColor?: number;
        opacity?: number;
        yOffset?: number;
        updateInterval?: number;
    });
    /**
     * Reference to the navmesh grid.
     * @type {NavMeshGrid}
     */
    navMeshGrid: NavMeshGrid;
    /**
     * Whether to show polygon surfaces.
     * @type {boolean}
     */
    showPolygons: boolean;
    /**
     * Whether to show polygon edges.
     * @type {boolean}
     */
    showEdges: boolean;
    /**
     * Whether to show portal edges.
     * @type {boolean}
     */
    showPortals: boolean;
    /**
     * Polygon fill color.
     * @type {number}
     */
    polygonColor: number;
    /**
     * Edge line color.
     * @type {number}
     */
    edgeColor: number;
    /**
     * Portal edge color.
     * @type {number}
     */
    portalColor: number;
    /**
     * Polygon opacity.
     * @type {number}
     */
    opacity: number;
    /**
     * Y offset for visualization elements.
     * @type {number}
     */
    yOffset: number;
    /**
     * Update interval in milliseconds.
     * @type {number}
     */
    updateInterval: number;
    /**
     * Three.js-style type flag.
     * @type {boolean}
     */
    isNavMeshGridHelper: boolean;
    _lastUpdate: number;
    _built: boolean;
    _polygonMesh: any;
    _edgeLines: any;
    _portalLines: any;
    _polygonMaterial: any;
    _edgeMaterial: any;
    _portalMaterial: any;
    /**
     * Update visualization - call each frame or periodically.
     */
    update(): void;
    /**
     * Build visualization from compiled navmesh data.
     *
     * @param {Object} data - Compiled navmesh data.
     * @private
     */
    private _buildVisualization;
    /**
     * Build polygon surface mesh.
     *
     * @param {Array} polygons - Array of polygon data.
     * @private
     */
    private _buildPolygonMesh;
    /**
     * Build edge lines for polygons.
     *
     * @param {Array} polygons - Array of polygon data.
     * @private
     */
    private _buildEdgeLines;
    /**
     * Build portal lines (shared edges between polygons).
     *
     * @param {Array} edges - Edge adjacency data.
     * @param {Array} polygons - Polygon data for vertex lookup.
     * @private
     */
    private _buildPortalLines;
    /**
     * Clear existing meshes.
     *
     * @private
     */
    private _clearMeshes;
    /**
     * Force refresh the visualization.
     */
    refresh(): void;
    /**
     * Dispose of the helper and release resources.
     */
    dispose(): void;
}
